fn reverse_digits(n: Int) -> Int {
    let mut rev = 0
    let mut num = n
    while num > 0 {
        let digit = num % 10
        rev = rev * 10 + digit
        num = num / 10
    }
    rev
}
fn main() {
    let number = 1234
    print(reverse_digits(number))
}

fn reverse_digits(n: Int) -> Str {
    let digits = vec()
    let mut num = n
    while num > 0 {
        let digit = num % 10
        digits = push(digits, digit)
        num = num / 10
    }
    let result = ""
    for d in digits {
        result = concat(result, int_to_str(d))
    }
    result
}
fn main() {
    let reversed = reverse_digits(1234)
    print_str(reversed)
}

fn reverse_digits(n: Int) -> Int {
    let mut result = 0
    let mut num = n
    while num > 0 {
        result = result * 10 + (num % 10)
        num = num / 10
    }
    result
}
fn main() {
